 private Map<String,Object> frozenSource(Map<String,Object> source){var selected=new LinkedHashMap<String,Object>();List<String> keys=source.containsKey("source_key")?List.of("id","book_id","kind","source_key","account_code","business_date","original_amount","remaining_amount","accumulated_amount","remaining_months","benefit_end"):List.of("id","type","hotel_id","company_id","business_date","amount","details","recognized_source_document_id","effective_contract_revision");for(String key:keys)selected.put(key,source.get(key));return map(json(output(selected)));}
 private void ensureOpen(TenantPrincipal p,Map<String,Object> plan,LocalDate month){var bk=book(p,id(plan.get("book_id")));if(month.isBefore(date(bk.get("start_month"))))throw conflict("不能回写账套切换前历史");var periods=jdbc.queryForList("select status from fa_period where tenant_id=:tenant and book_id=:book and month=:month for update",base(p).addValue("book",plan.get("book_id")).addValue("month",month));if(!periods.isEmpty()&&!"OPEN".equals(periods.getFirst().get("status")))throw conflict("计提月份已关账，包括零额月份也不能新增历史任务");}
 private UUID director(TenantPrincipal p,UUID hotel){var row=one("select c.director_account_id from finance_store_config c join user_account u on u.tenant_id=c.tenant_id and u.id=c.director_account_id where c.tenant_id=:tenant and c.hotel_id=:hotel and c.enabled and c.workflow_version=2 and u.status='ACTIVE'",base(p).addValue("hotel",hotel));return id(row.get("director_account_id"));}
 private TenantPrincipal read(){return prepare("finance.read","finance.accounting.read","finance.review");}
 private TenantPrincipal write(){var p=prepare("finance.accounting.write");access.requireAnyPermission("finance.read","finance.accounting.read");return p;}
